CREATE FUNCTION dbo.mogudi_tafkik  (@Forms___F_MENU_ANBAR___DT2 BIGINT,  @Forms___F_MENU_ANBAR___MANBAR nvarchar(10)) RETURNS Table  AS  RETURN ( SELECT     CODE, MAND, ANBAR, ANBARN, FII, MABLK, NAME, NAMES, VCOD, GRCOD, GRNAME, MANDF, N_FANI, NESBAT, MEGHBAR, bsef, nsef, maxm, minm, VAZN, VAZNK,menuit,MABL_F,B_SEF,fisiclymand,MAX_M,MEGHRES,POSITION  FROM         dbo.AKMOGUDI_KOL_ANBAR(@Forms___F_MENU_ANBAR___DT2, @Forms___F_MENU_ANBAR___MANBAR) AKMOGUDI_KOL_ANBAR  GROUP BY CODE, MAND, ANBAR, ANBARN, FII, MABLK, NAME, NAMES, VCOD, GRCOD, GRNAME, MANDF, N_FANI, NESBAT, MEGHBAR, bsef, nsef, maxm, minm, VAZN, VAZNK ,menuit,MABL_F,B_SEF,fisiclymand,MAX_M,MEGHRES,POSITION)
